ST.xhtml:p:
RTrigge(CLK := g_bAirCalExecute);
IF RTrigge.Q THEN
  For i := 0 TO 10 BY 1 DO 
    g_StAirCal[i].Ao := 0.0;
    g_StAirCal[i].Pressure := 0.0;  
    g_StAirCal[i].Done := FALSE;  (*初始化空气气压标定数组*)
  END_FOR;
  CalNum := -1;
  AirCalDeltMax := 0.0;
  g_bAirCalDone := FALSE;
  AirCalState := 10;
END_IF;

CASE AirCalState OF
  0:
    AirCalState := 0;
  10:(*初始化气体*)
    g_boMasterValve := FALSE;
    g_uoSharePressureOut := 0;
    g_uoMasterPressureOut := 0;
    g_boAirValve:= FALSE;
    g_boOxygenValve := FALSE;
    g_boNirtogenValve := FALSE;
    g_uoAirPressureOut := 0;
    g_uoNirtogenPressureOut := 0;
    g_uoOxygenPressureOut := 0;   
    AirCalState := 20; 
  20:(*按采集点顺序输出标定电压*)
    AirCalTon1(IN:= FALSE);
    AirCalTon2(IN:= FALSE);
    AirCalTon3(IN:= FALSE);
    CalNum := CalNum +1;
    IF CalNum = 0 THEN
      DAOutputVol := 0.2;
      AirCalState := 50;
    ELSIF CalNum = 1 THEN
      DAOutputVol := 0.5;
      AirCalState := 50;
    ELSIF CalNum = 2 THEN
      DAOutputVol := 1.0;
      AirCalState := 50;
    ELSIF CalNum = 3 THEN
      DAOutputVol := 2.4;
      AirCalState := 50;
    ELSIF CalNum = 4 THEN
      DAOutputVol := 3.6;
      AirCalState := 50;
    ELSIF CalNum = 5 THEN
      DAOutputVol := 5.0;
      AirCalState := 50;
    ELSIF CalNum = 6 THEN
      DAOutputVol := 10.0;
      AirCalState := 50;
    ELSE
      AirCalState := 100;
    END_IF;
  50:(*输出电压出气*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAOutputVol);   
    bDAOutputVolEnable :=TRUE;

    AirCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF AirCalTon1.Q THEN
      AirCalTon1(IN:= FALSE);
      AirCalState := 60;
    END_IF;
  60:(*采集气压*)   
    AirCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)
    AirCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage >0.0),PT := T#1000ms); (*气压方差稳定*)
    IF AirCalTon3.Q OR AirCalTon2.Q THEN
      g_StAirCal[CalNum].Ao := DAOutputVol;
      g_StAirCal[CalNum].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StAirCal[CalNum].Done := TRUE;
      AirCalTon2(IN:= FALSE);
      AirCalTon3(IN:= FALSE);
      AirCalState := 20;
    END_IF;
  100:(*找最大气压,气压标定数据差值最大的区段*)   
    STAirCalDelt[1] := g_StAirCal[1].Pressure - g_StAirCal[0].Pressure;
    STAirCalDelt[2] := g_StAirCal[2].Pressure - g_StAirCal[1].Pressure;
    STAirCalDelt[3] := g_StAirCal[3].Pressure - g_StAirCal[2].Pressure;
    STAirCalDelt[4] := g_StAirCal[4].Pressure - g_StAirCal[3].Pressure;
    STAirCalDelt[5] := g_StAirCal[5].Pressure - g_StAirCal[4].Pressure;
    STAirCalDelt[6] := g_StAirCal[6].Pressure - g_StAirCal[5].Pressure; 
    For i := 1 to 6 BY 1 DO 
      IF STAirCalDelt[i] > AirCalDeltMax THEN
        AirCalDeltMax := STAirCalDelt[i];
        AirCalDeltMaxi := i;
      END_IF;
    END_FOR; 
    AirCalState := 110; 
  110:(*补采点判断*)
    IF g_StAirCal[AirCalDeltMaxi].Ao > 2.4 THEN  (*补2个点*)
      DAVolRepair1 := g_StAirCal[AirCalDeltMaxi-1].Ao + (g_StAirCal[AirCalDeltMaxi].Ao - g_StAirCal[AirCalDeltMaxi-1].Ao)/3.0;
      DAVolRepair2 := g_StAirCal[AirCalDeltMaxi-1].Ao + 2.0*(g_StAirCal[AirCalDeltMaxi].Ao - g_StAirCal[AirCalDeltMaxi-1].Ao)/3.0;
    ELSE     (*补1个点*)
      DAVolRepair1 := g_StAirCal[AirCalDeltMaxi-1].Ao + (g_StAirCal[AirCalDeltMaxi].Ao - g_StAirCal[AirCalDeltMaxi-1].Ao)/2.0;
    END_IF;
    AirCalState := 120;
  120:(*补采点1*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAVolRepair1);   
    bDAOutputVolEnable :=TRUE;

    AirCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF AirCalTon1.Q THEN
      AirCalTon1(IN:= FALSE);
      AirCalState := 130;
    END_IF;
  130:(*采集气压*)    
    AirCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)
    AirCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage >0.0),PT := T#1000ms); (*气压方差稳定*)
    IF AirCalTon3.Q OR AirCalTon2.Q THEN
      g_StAirCal[7].Ao := DAVolRepair1;
      g_StAirCal[7].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StAirCal[7].Done := TRUE;
      AirCalTon2(IN:= FALSE);
      AirCalTon3(IN:= FALSE);
      AirCalState := 140;
    END_IF; 
  140:(*是否补采点2*)   
    IF g_StAirCal[AirCalDeltMaxi].Ao > 2.4 THEN
      AirCalState := 150;
    ELSE
      AirCalState := 200;
    END_IF;
  150:(*补采点2*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAVolRepair2);   
    bDAOutputVolEnable :=TRUE;

    AirCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF AirCalTon1.Q THEN
      AirCalTon1(IN:= FALSE);
      AirCalState := 160;
    END_IF;
  160:(*采集气压*)
    AirCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)   
    AirCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage >0.0),PT := T#1000ms); (*气压方差稳定*)
    IF AirCalTon3.Q OR AirCalTon2.Q THEN
      g_StAirCal[8].Ao := DAVolRepair2;
      g_StAirCal[8].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StAirCal[8].Done := TRUE;
      AirCalTon2(IN:= FALSE);
      AirCalTon3(IN:= FALSE);
      AirCalState := 200;
    END_IF; 

  200:(*关气,气压标定完成*)
      (*气压标定结果数组冒泡排序,排除0组*)
    FOR i := 0 TO 8 BY 1 DO
      FOR j := 0 TO (8-i) BY 1 DO
        IF g_StAirCal[j].Ao > g_StAirCal[j+1].Ao AND g_StAirCal[j].Ao<>0.0 AND g_StAirCal[j+1].Ao<>0.0 THEN
          temp := g_StAirCal[j];
          g_StAirCal[j] := g_StAirCal[j+1];
          g_StAirCal[j+1] := temp;       
        END_IF;
      END_FOR;
    END_FOR;
    bDAOutputVolEnable := FALSE;
    g_bAirCalExecute := FALSE;
    g_bAirCalDone := TRUE;
    AirCalState := 0;
END_CASE;

(*空气电压输出*)
IF bDAOutputVolEnable THEN
    g_boMasterValve := TRUE;
    g_uoSharePressureOut := DAOutputVolAna;
    g_uoMasterPressureOut := DAOutputVolAna;
    g_boAirValve:= TRUE;
    g_uoAirPressureOut := DAOutputVolAna; 
END_IF;
FTrigge1(CLK := bDAOutputVolEnable);
IF FTrigge1.Q THEN
  g_boMasterValve := FALSE;
  g_uoSharePressureOut := 0;
  g_uoMasterPressureOut := 0;
  g_boAirValve:= FALSE;
  g_uoAirPressureOut := 0; 
END_IF;

IF g_bPlcResetBuffer OR g_bGasCalStop THEN
  bDAOutputVolEnable:=FALSE;
  g_bAirCalExecute := FALSE;
  AirCalState := 0;
  g_bGasCalStop := FALSE;
END_IF;
